}
.ov-gallery__tools .ov-seg{ padding:2px 10px !important; }
.ov-gallery__tools .ov-seg button{ clip-path:var(--vc-tag); border-radius:0 !important; padding-inline:10px; }
/* Home: Conversation, Roleplay and Game are coffin tags like Professor and Widgets */
[data-component="CenterContent"] .mari-chrome-control[data-home-chat-mode]{
  border:0 !important; border-radius:0 !important; clip-path:var(--vc-tag);
  box-shadow:inset 0 0 0 1.5px var(--vc-trim) !important;
  background:var(--vc-tag-edge), var(--vc-bar) !important;
  padding-inline:16px !important;
}
/* phone Chats toolbar: search, tags and "..." are coffin tags like New */
.ovm-sidepage .ovm-chats-tools .mari-chrome-field,
.ovm-sidepage [data-mari-part="tag-filter"],
.ovm-sidepage .ovm-chats-more__btn,
.mari-status-footer .mari-chrome-control,
.mari-status-footer .mari-chrome-field{
  border:0 !important; border-radius:0 !important; clip-path:var(--vc-tag);
  box-shadow:inset 0 0 0 1.5px var(--vc-trim) !important;
  background:var(--vc-tag-edge), var(--vc-bar) !important;
}
.ovm-sidepage [data-mari-part="tag-filter"], .ovm-sidepage .ovm-chats-more__btn{ min-width:3rem; }
/* phone/tablet Chat settings: the rows are coffin tags, the switch tiles and Edit have cut corners,
   like the rest of the theme (the drawer is square, not rounded) */
.ov-cs.ov-cs [data-ovm-cs-view] .mari-drawer.ovm-cs-row,
.ov-cs.ov-cs [data-ovm-cs-view] .mari-drawer[data-chat-settings-section="connection"],
.ov-cs.ov-cs [data-ovm-cs-view] [data-ovm-quick] > .mari-drawer,
.ov-cs.ov-cs [data-ovm-cs-view="all"] > [data-ovm-quick],
.ov-cs.ov-cs [data-ovm-cs-view] .ovm-cs-row__btn,
.ov-cs.ov-cs [data-ovm-cs-view] .ovm-csq__all{ border-radius:0 !important; clip-path:var(--vc-tag); }
.ov-cs.ov-cs [data-ovm-cs-view] .ovm-cs-row__btn,
.ov-cs.ov-cs [data-ovm-cs-view] .ovm-csq__all,
.ov-cs.ov-cs [data-ovm-cs-view] .mari-drawer[data-chat-settings-section="connection"]{ padding-inline:1.25rem !important; }
.ov-cs.ov-cs [data-ovm-cs-view] .ovm-csq__switch{ border-radius:0 !important; clip-path:var(--vc-cut); }
.ov-cs .ov-edbtn{ border-radius:0 !important; clip-path:var(--vc-tag); padding-inline:16px !important; }
/* the Juno / Online chip over a conversation is an opaque tag, so messages never show through it */
[data-mari-part="chat-header"] > *{
  background:var(--vc-tag-edge), var(--vc-bar) !important;
  box-shadow:inset 0 0 0 1.5px var(--vc-trim) !important;
  padding-inline:14px 16px !important;
}


